// DeleteUniqueIndexCache 删除索引存在的缓存
func (g *GoodRecommendationCategoryRepo) DeleteIndexCache(ctx context.Context, data ...*yanxue_model.GoodRecommendationCategory) error {
	KeyMap := make(map[string]struct{})
	keys := make([]string, 0)
	keys = append(keys, g.cache.Key(CacheGoodRecommendationCategoryByConditionPrefix))
	for _, item := range data {
		if item != nil {
			KeyMap[g.cache.Key(CacheGoodRecommendationCategoryByIDPrefix, item.ID)] = struct{}{}
			KeyMap[g.cache.Key(CacheGoodRecommendationCategoryByNamePrefix, item.Name)] = struct{}{}
		}
	}
	for item := range KeyMap {
		keys = append(keys, item)
	}
	err := g.cache.DelBatch(ctx, keys)
	if err != nil {
		return err
	}
	return nil
}
